#!/usr/bin/env python3
"""Compare two S0 semantic snapshot JSON files generated by S0SemanticProbe."""

from __future__ import annotations

import argparse
import json
import pathlib
import re
import sys
from collections import defaultdict
from typing import Any

KNOWN_TIME_FIELD_NAMES = frozenset(
    {
        "unitytime",
        "unityfixedtime",
        "unityunscaledtime",
        "unitytimesincelevelload",
        "unityframecount",
        "realtimesincestartup",
        "realtimesincestartupasdouble",
        "unscaledtime",
        "unscaledtimeasdouble",
        "fixedtime",
        "fixedtimeasdouble",
        "timeasdouble",
        "timesincelevelload",
        "timesincelevelloadasdouble",
        "lastgameupdatenativeframe",
        "startmenutime",
        "nativeframe",
        "framecount",
        "currenttick",
    }
)

_TRAILING_INDEX_RE = re.compile(r"(?:\[[^\]]*\])+$")
_BACKING_FIELD_RE = re.compile(r"^<(.+)>k__BackingField$")


def classify_prefix(key: str) -> str:
    if key.startswith("globalVars."):
        return "globalVars"
    if key.startswith("static/"):
        return "static"
    if key.startswith("ddol/Knight:") and "HeroController" in key:
        return "Knight.HeroController"
    if key.startswith("ddol/Knight:") and "PlayMakerFSM" in key:
        return "Knight.FSM"
    if key.startswith("ddol/Knight/"):
        return "Knight.Children"
    if key.startswith("ddol/_GameManager"):
        return "GameManager"
    if key.startswith("ddol/_GameCameras"):
        return "GameCameras"
    if key.startswith("ddol/_AudioManager") or "Audio" in key:
        return "AudioManager"
    if key.startswith("ddol/_UIManager"):
        return "UIManager"
    if key.startswith("ddol/Pool") or "ObjectPool" in key:
        return "ObjectPool"
    return "OtherDDOL"


def extract_leaf_field_name(key: str) -> str:
    """Extract the normalized leaf field name from a flattened semantic probe key."""
    stripped = _TRAILING_INDEX_RE.sub("", key)
    last_sep = max(stripped.rfind("."), stripped.rfind(":"), stripped.rfind("/"))
    leaf = stripped[last_sep + 1 :] if last_sep >= 0 else stripped
    backing_match = _BACKING_FIELD_RE.match(leaf)
    if backing_match:
        leaf = backing_match.group(1)
    return leaf


def is_known_time_field(key: str) -> bool:
    """Return True when the key represents a pure absolute clock or frame counter."""
    leaf = extract_leaf_field_name(key).lower()
    return leaf in KNOWN_TIME_FIELD_NAMES


def compare_snapshots(
    left: dict[str, Any],
    right: dict[str, Any],
    ignore_known_time_fields: bool = False,
) -> dict[str, Any]:
    """Compare two parsed S0 semantic snapshot payloads and return structured diff summary."""
    lflat = left.get("flat", {})
    rflat = right.get("flat", {})
    all_keys = sorted(set(lflat.keys()) | set(rflat.keys()))

    diffs = []
    ignored_keys = []
    by_domain: dict[str, list[dict[str, Any]]] = defaultdict(list)

    for k in all_keys:
        in_l = k in lflat
        in_r = k in rflat
        lv = lflat.get(k)
        rv = rflat.get(k)
        if not in_l or not in_r or lv != rv:
            if ignore_known_time_fields and is_known_time_field(k):
                ignored_keys.append(k)
                continue
            rec = {
                "path": k,
                "domain": classify_prefix(k),
                "left": lv if in_l else "<MISSING>",
                "right": rv if in_r else "<MISSING>",
            }
            diffs.append(rec)
            by_domain[rec["domain"]].append(rec)

    return {
        "leftMeta": left.get("meta"),
        "rightMeta": right.get("meta"),
        "totalFlatKeysLeft": len(lflat),
        "totalFlatKeysRight": len(rflat),
        "totalDiffCount": len(diffs),
        "ignoredDiffCount": len(ignored_keys),
        "ignoredKeys": ignored_keys,
        "diffCountByDomain": {d: len(v) for d, v in sorted(by_domain.items())},
        "diffs": diffs,
    }


def _md_inline(value: Any, max_len: int = 180) -> str:
    text = json.dumps(value, ensure_ascii=False) if isinstance(value, (dict, list)) else str(value)
    text = text.replace("\r", "\\r").replace("\n", "\\n").replace("`", "'").replace("|", "\\|")
    if len(text) > max_len:
        text = text[: max_len - 3] + "..."
    return f"`{text}`"


def _format_meta_line(label: str, path_str: str, meta: Any) -> str:
    if not isinstance(meta, dict):
        return f"- **{label}**: `{path_str}`"
    parts = []
    if meta.get("segment"):
        parts.append(f"segment=`{meta['segment']}`")
    if meta.get("ordinal") is not None:
        parts.append(f"ordinal=`{meta['ordinal']}`")
    if meta.get("sourceScene") or meta.get("targetScene"):
        parts.append(f"transition=`{meta.get('sourceScene', '')}` -> `{meta.get('targetScene', '')}`")
    if meta.get("entryGate"):
        parts.append(f"gate=`{meta['entryGate']}`")
    if meta.get("movieFrame") is not None:
        parts.append(f"movie=`{meta['movieFrame']}`")
    if meta.get("nativeFrame") is not None:
        parts.append(f"native=`{meta['nativeFrame']}`")
    detail = ", ".join(parts) if parts else "no metadata"
    return f"- **{label}**: `{path_str}` ({detail})"


def render_markdown_report(
    summary: dict[str, Any],
    left_path: str,
    right_path: str,
    ignore_known_time_fields: bool = False,
    max_diffs: int = 100,
) -> str:
    """Render a human-readable Markdown diff report."""
    total_diffs = int(summary["totalDiffCount"])
    ignored_count = int(summary.get("ignoredDiffCount", 0))
    status = "PASS" if total_diffs == 0 else "FAIL"

    lines = [
        "# S0 Semantic Snapshot Diff Report",
        "",
        f"- **Result**: **{status}**",
        _format_meta_line("Left", left_path, summary.get("leftMeta")),
        _format_meta_line("Right", right_path, summary.get("rightMeta")),
        f"- **Flat Keys**: left=`{summary['totalFlatKeysLeft']}`, right=`{summary['totalFlatKeysRight']}`",
        f"- **Total Diffs (after filter)**: `{total_diffs}`",
        f"- **Ignore Known Time Fields**: `{str(ignore_known_time_fields).lower()}` (ignored=`{ignored_count}`)",
        "",
        "## Diff Count by Domain",
        "",
        "| Domain | Diff Count |",
        "| --- | ---: |",
    ]

    domain_counts = summary.get("diffCountByDomain") or {}
    if domain_counts:
        for domain, count in sorted(domain_counts.items()):
            lines.append(f"| `{domain}` | {count} |")
    else:
        lines.append("| *(none)* | 0 |")

    diffs = summary.get("diffs") or []
    lines.append("")
    if total_diffs == 0:
        lines.append("## Detailed Diffs")
        lines.append("")
        lines.append("No semantic state differences detected.")
    else:
        shown_items = diffs[:max_diffs]
        lines.append(f"## Detailed Diffs (showing {len(shown_items)} of {total_diffs})")
        grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for item in shown_items:
            grouped[item["domain"]].append(item)

        for domain in sorted(grouped.keys()):
            domain_total = domain_counts.get(domain, len(grouped[domain]))
            lines.append("")
            lines.append(f"### {domain} (showing {len(grouped[domain])} of {domain_total})")
            lines.append("")
            lines.append("| Path | Left | Right |")
            lines.append("| --- | --- | --- |")
            for item in grouped[domain]:
                lines.append(
                    f"| {_md_inline(item['path'], max_len=240)} | {_md_inline(item['left'])} | {_md_inline(item['right'])} |"
                )

    ignored_keys = summary.get("ignoredKeys") or []
    if ignored_keys:
        shown_ignored = ignored_keys[:max_diffs]
        lines.append("")
        lines.append(f"## Ignored Known Time/Frame Keys (showing {len(shown_ignored)} of {len(ignored_keys)})")
        lines.append("")
        for key in shown_ignored:
            lines.append(f"- {_md_inline(key, max_len=240)}")

    lines.append("")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--left", required=True)
    parser.add_argument("--right", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--ignore-known-time-fields", action="store_true")
    parser.add_argument("--markdown-output", default=None)
    parser.add_argument("--fail-on-diff", action="store_true")
    args = parser.parse_args(argv)

    left = json.loads(pathlib.Path(args.left).read_text(encoding="utf-8"))
    right = json.loads(pathlib.Path(args.right).read_text(encoding="utf-8"))

    summary = compare_snapshots(
        left,
        right,
        ignore_known_time_fields=args.ignore_known_time_fields,
    )

    out_path = pathlib.Path(args.output)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding="utf-8")

    if args.markdown_output:
        md_path = pathlib.Path(args.markdown_output)
        md_path.parent.mkdir(parents=True, exist_ok=True)
        md_text = render_markdown_report(
            summary,
            left_path=args.left,
            right_path=args.right,
            ignore_known_time_fields=args.ignore_known_time_fields,
        )
        md_path.write_text(md_text, encoding="utf-8")

    print(
        f"Compared {args.left} vs {args.right}: {summary['totalDiffCount']} diffs "
        f"(ignored {summary['ignoredDiffCount']}) written to {args.output}"
    )
    for d, count in sorted(summary["diffCountByDomain"].items()):
        print(f"  {d}: {count}")

    if args.fail_on_diff and summary["totalDiffCount"] > 0:
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
